import json,re,hashlib
from pathlib import Path
root=Path("/home/sasaki/datasets/openloris/corridor1-1-m8-bounded-native-v1/tier-2500-ann")
old=Path("/home/sasaki/datasets/openloris/corridor1-1-m8-dense256x2-2500-ann-gap128-local32-8n-v1/rig-legacy-cap256/model/component-000")
out={}
for arm in ["legacy","policy-a","policy-b"]:
 model=root/arm/"model/component-000"; log=(root/(arm+".log")).read_text(); time=(root/(arm+".time")).read_text()
 assert "Exit status: 0" in time
 hashes={}
 for name in ["cameras.txt","images.txt","points3D.txt"]:
  data=(model/name).read_bytes()
  assert data==(old/name).read_bytes()
  hashes[name]=hashlib.sha256(data).hexdigest()
 match=re.search(r"rig-multimodel result: models=(\d+) registered_frames=(\d+)/(\d+) registered_images=(\d+)/(\d+)",log)
 assert match and tuple(map(int,match.groups()))==(1,1250,1250,2500,2500)
 elapsed=re.search(r"Elapsed \(wall clock\) time \(h:mm:ss or m:ss\):\s*(\S+)",time)[1];wall=0
 for part in elapsed.split(":"):wall=60*wall+float(part)
 out[arm]={"mapper_seconds":float(re.findall(r"mapper_seconds=([0-9.]+)",log)[-1]),"wall_seconds":wall,"peak_rss_kib":int(re.search(r"Maximum resident set size \(kbytes\):\s*(\d+)",time)[1]),"direct_selections":log.count("selected=Legacy"),"qr_selections":log.count("selected=MatrixFreeQr"),"model_sha256":hashes,"log":log,"time_output":time}
print(json.dumps({"all_models_exact_to_historical":True,"full_registration":True,"runs":out}))
